begin;
do $setup$
declare c uuid:='4b060000-0000-4000-8000-000000000001';u uuid:='4b060000-0000-4000-8000-000000000002';cfg uuid;rs uuid;r jsonb;controls jsonb;role text;a uuid;
begin
  insert into public.companies(id,legal_name,display_name) values(c,'M4B operaciones','M4B operaciones');insert into auth.users(id,aud,role,email,encrypted_password) values(u,'authenticated','authenticated','m4b-ops@example.com','');insert into public.user_roles(user_id,role_id,company_id) select u,id,c from public.roles where code='direccion_admin';perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',u::text,true);
  insert into public.accounting_accounts(company_id,code,name,account_type,normal_balance,level) select c,lpad(n::text,4,'0'),'Cuenta '||n,case when n between 11 and 30 then 'expense' else 'asset' end,case when n in(2,7,9) or n between 11 and 30 then 'credit' else 'debit' end,1 from generate_series(1,30)n;
  select jsonb_object_agg(k,a.id) into controls from (values('accounts_receivable','0001'),('accounts_payable','0002'),('inventory','0003'),('cash','0004'),('banks','0005'),('vat_pending','0006'),('vat_collected','0007'),('vat_paid','0008'),('withholdings','0009'))x(k,code) join public.accounting_accounts a on a.company_id=c and a.code=x.code;
  r:=public.save_accounting_config(c,'MXN',current_date,'{"format":"4"}','{"vat_pending":"x","vat_collected":"x","vat_paid":"x","withholdings":"x"}',jsonb_build_object('adjustments',u,'close',u,'reopen',u),'M4B operaciones',controls);cfg:=(r->>'id')::uuid;perform public.approve_accounting_config(cfg);perform public.create_accounting_period(c,to_char(current_date,'YYYY-MM'),date_trunc('month',current_date)::date,(date_trunc('month',current_date)+interval '1 month' - interval '1 day')::date);
  r:=public.create_accounting_event_rule_set(c,'replacement_cost','{"sale":"confirmation","cash":"movement"}','Matriz operativa');rs:=(r->>'id')::uuid;
  for role in select unnest(array['sales_revenue','sales_discounts','cost_of_goods_sold','goods_received_not_invoiced','purchase_variance','supplier_expense','cash_opening_offset','cash_close_offset','cash_movement_offset','cash_over_short','supplier_credit_note_offset','inventory_adjustment']) loop select id into a from public.accounting_accounts where company_id=c and code=lpad((10+(select count(*) from public.accounting_event_role_accounts where rule_set_id=rs)+1)::text,4,'0');perform public.set_accounting_event_role_account(rs,role,a);end loop;perform public.approve_accounting_event_rule_set(rs,'Prueba operativa');
  insert into public.customers(id,company_id,code,display_name,credit_enabled,credit_limit,credit_term_days,created_by) values('4b060000-0000-4000-8000-000000000010',c,'CLI-M4B','Cliente M4B',true,1000,30,u);
  insert into public.payment_methods(id,company_id,code,display_name,settlement_kind) values('4b060000-0000-4000-8000-000000000011',c,'TRANSF','Transferencia','external');
  insert into public.locations(id,company_id,external_code,name,location_type,classification_source) values('4b060000-0000-4000-8000-000000000014',c,'M4B','M4B','sucursal','manual_review');insert into public.cash_registers(id,company_id,location_id,code,display_name,currency_code) values('4b060000-0000-4000-8000-000000000015',c,'4b060000-0000-4000-8000-000000000014','M4B','Caja M4B','MXN');insert into public.cash_sessions(id,company_id,cash_register_id,location_id,opened_by,opening_amount) values('4b060000-0000-4000-8000-000000000016',c,'4b060000-0000-4000-8000-000000000015','4b060000-0000-4000-8000-000000000014',u,100);insert into public.cash_movements(id,company_id,cash_session_id,movement_type,amount,actor_id,reason) values('4b060000-0000-4000-8000-000000000017',c,'4b060000-0000-4000-8000-000000000016','paid_in',20,u,'Entrada de prueba');
  insert into public.units_of_measure(id,company_id,code,name) values('4b060000-0000-4000-8000-000000000020',c,'PZA','Pieza');insert into public.products(id,company_id,alpha_sku,name,unit,product_type,is_active,is_sellable,is_inventory_tracked,sales_unit_id,commercial_review_required) values('4b060000-0000-4000-8000-000000000021',c,'M4B-SKU','Producto M4B','PZA','P. TERMINADO',true,true,true,'4b060000-0000-4000-8000-000000000020',false);insert into public.product_costs(company_id,product_id,cost_type,amount,currency_code,valid_from,created_by) values(c,'4b060000-0000-4000-8000-000000000021','replacement_cost',60,'MXN',now()-interval '1 day',u);
  insert into public.sales(id,company_id,location_id,cash_register_id,cash_session_id,cashier_id,customer_id,sale_type,currency_code,subtotal_amount,discount_amount,tax_amount,total_amount,due_date,client_request_id) values('4b060000-0000-4000-8000-000000000022',c,'4b060000-0000-4000-8000-000000000014','4b060000-0000-4000-8000-000000000015','4b060000-0000-4000-8000-000000000016',u,'4b060000-0000-4000-8000-000000000010','credit','MXN',100,0,16,116,current_date+30,'4b060000-0000-4000-8000-000000000023');insert into public.sale_items(id,sale_id,product_id,product_code,product_name,unit_name,quantity,unit_price_amount,gross_amount,discount_percent,discount_amount,taxable_amount,tax_amount,total_amount) values('4b060000-0000-4000-8000-000000000024','4b060000-0000-4000-8000-000000000022','4b060000-0000-4000-8000-000000000021','M4B-SKU','Producto M4B','PZA',1,100,100,0,0,100,16,116);insert into public.inventory_balances(company_id,location_id,product_id,quantity_on_hand) values(c,'4b060000-0000-4000-8000-000000000014','4b060000-0000-4000-8000-000000000021',9);insert into public.inventory_ledger(company_id,location_id,product_id,quantity_delta,balance_after,movement_type,sale_item_id,actor_id) values(c,'4b060000-0000-4000-8000-000000000014','4b060000-0000-4000-8000-000000000021',-1,9,'sale','4b060000-0000-4000-8000-000000000024',u);
  insert into public.customer_receivables(id,company_id,customer_id,sale_id,due_date,original_amount,outstanding_amount,source_kind) values('4b060000-0000-4000-8000-000000000030',c,'4b060000-0000-4000-8000-000000000010','4b060000-0000-4000-8000-000000000022',current_date+30,116,58,'sale');
  insert into public.receivable_payments(id,company_id,customer_id,payment_method_id,payment_method_code,settlement_kind,amount,client_request_id,received_by) values('4b060000-0000-4000-8000-000000000012',c,'4b060000-0000-4000-8000-000000000010','4b060000-0000-4000-8000-000000000011','TRANSF','external',58,'4b060000-0000-4000-8000-000000000013',u);
  insert into public.receivable_payment_applications(receivable_payment_id,receivable_id,amount) values('4b060000-0000-4000-8000-000000000012','4b060000-0000-4000-8000-000000000030',58);
end;$setup$;
set constraints all immediate;
do $assert$
declare c uuid:='4b060000-0000-4000-8000-000000000001';u uuid:='4b060000-0000-4000-8000-000000000002';d numeric;h numeric;recognized numeric;cogs numeric;
begin
  if (select count(*) from public.accounting_events where company_id=c and status='posted')<>4 then raise exception 'Cobro, apertura, movimiento y venta no generaron cuatro eventos.';end if;
  select recognized_cost_amount into recognized from public.sale_items where id='4b060000-0000-4000-8000-000000000024';
  if recognized<>60 then raise exception 'La partida vendida no congeló el costo reconocido: %',recognized;end if;
  select (line->>'debit')::numeric into cogs from public.accounting_events e cross join lateral jsonb_array_elements(e.requested_lines) line
  where e.company_id=c and e.event_type='sale_confirmed' and line->>'role'='cost_of_goods_sold';
  if cogs<>60 then raise exception 'La póliza de venta no usó el costo reconocido de la partida: %',cogs;end if;
  select sum(l.debit),sum(l.credit) into d,h from public.accounting_journal_lines l where l.company_id=c;if d<>362 or h<>362 then raise exception 'Pólizas operativas desbalanceadas: % / %',d,h;end if;
  if (select requested_lines from public.accounting_events where company_id=c and event_type='receivable_payment_confirmed')->2->>'role'<>'vat_pending' or (select requested_lines from public.accounting_events where company_id=c and event_type='receivable_payment_confirmed')->3->>'role'<>'vat_collected' then raise exception 'El cobro parcial no reclasificó IVA efectivo.';end if;
  perform public.reverse_receivable_payment(c,'4b060000-0000-4000-8000-000000000012','Reversa de cobro aplicada','4b060000-0000-4000-8000-000000000019');if (select outstanding_amount from public.customer_receivables where id='4b060000-0000-4000-8000-000000000030')<>116 or not exists(select 1 from public.accounting_events where company_id=c and event_type='receivable_payment_reversed' and status='posted') then raise exception 'La reversa de cobro no restauró CxC y póliza.';end if;
  perform public.reverse_cash_drawer_movement(c,'4b060000-0000-4000-8000-000000000017','Reversa de prueba','4b060000-0000-4000-8000-000000000018');if not exists(select 1 from public.accounting_events where company_id=c and event_type='cash_movement_reversed' and status='posted') then raise exception 'El contramovimiento no revirtió su póliza.';end if;
  perform public.cancel_sale(c,'4b060000-0000-4000-8000-000000000022','Cancelación de prueba','4b060000-0000-4000-8000-000000000025');if not exists(select 1 from public.accounting_events where company_id=c and event_type='sale_cancelled' and status='posted') or (select quantity_on_hand from public.inventory_balances where location_id='4b060000-0000-4000-8000-000000000014' and product_id='4b060000-0000-4000-8000-000000000021')<>10 then raise exception 'La cancelación no neutralizó venta e inventario.';end if;
  if exists(select e.source_entity_type,e.source_entity_id,l.account_id from public.accounting_events e join public.accounting_journal_entries j on j.accounting_event_id=e.id join public.accounting_journal_lines l on l.journal_entry_id=j.id where e.company_id=c and ((e.source_entity_type='receivable_payment' and e.source_entity_id='4b060000-0000-4000-8000-000000000012') or (e.source_entity_type='cash_movement' and e.source_entity_id='4b060000-0000-4000-8000-000000000017') or (e.source_entity_type='sale' and e.source_entity_id='4b060000-0000-4000-8000-000000000022')) group by e.source_entity_type,e.source_entity_id,l.account_id having abs(sum(l.debit-l.credit))>0.000001) then raise exception 'Una reversa operativa no neutralizó exactamente su póliza original.';end if;
  update public.cash_sessions set status='closed',expected_closing_amount=100,counted_closing_amount=110,variance_amount=10,close_requested_by=u,variance_reason='Sobrante',variance_approved_by=u,variance_approved_at=now(),closed_at=now() where id='4b060000-0000-4000-8000-000000000016';
  if not exists(select 1 from public.accounting_events where company_id=c and event_type='cash_closed' and status='posted') then raise exception 'El cierre no produjo póliza.';end if;
  select sum(l.debit),sum(l.credit) into d,h from public.accounting_journal_lines l join public.accounting_journal_entries e on e.id=l.journal_entry_id join public.accounting_events ev on ev.id=e.accounting_event_id where ev.event_type='cash_closed' and ev.company_id=c;if d<>10 or h<>10 then raise exception 'La diferencia de cierre quedó desbalanceada o vació la caja: % / %',d,h;end if;
  if exists(select 1 from public.accounting_events ev cross join lateral jsonb_array_elements(ev.requested_lines) line where ev.company_id=c and ev.event_type='cash_closed' and line->>'role'='cash_close_offset') then raise exception 'El cierre creó un retiro físico ficticio.';end if;
  raise notice 'M4B/M4D3 captura: cobro, caja, contramovimiento y cierre sin traslado ficticio validados.';
end;$assert$;
rollback;
